import{_ as e,o as a,c as r,ag as d}from"./chunks/framework.ePeAWSvT.js";const p=JSON.parse('{"title":"架构决策记录（ADR）","description":"","frontmatter":{},"headers":[],"relativePath":"adr/index.md","filePath":"adr/index.md"}'),o={name:"adr/index.md"};function i(l,t,n,s,h,c){return a(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="架构决策记录-adr" tabindex="-1">架构决策记录（ADR） <a class="header-anchor" href="#架构决策记录-adr" aria-label="Permalink to &quot;架构决策记录（ADR）&quot;">​</a></h1><p>ADR（Architecture Decision Record）记录项目中<strong>影响架构方向的决策</strong>：背景是什么、决定了什么、为什么、放弃了哪些备选。</p><h2 id="为什么需要-adr" tabindex="-1">为什么需要 ADR <a class="header-anchor" href="#为什么需要-adr" aria-label="Permalink to &quot;为什么需要 ADR&quot;">​</a></h2><ul><li>Issue 和 PR 记录&quot;做了什么&quot;，但&quot;为什么这么做、当时还考虑过什么&quot;随时间丢失</li><li>记忆系统这类长周期演进的模块，决策依据（调研数据、版本限制）需要固化下来，供后来者（包括未来的自己和 AI agent）复审</li><li>决策变更时不删除旧 ADR，而是新增一条并标记旧条目为 Superseded，保留演进轨迹</li></ul><h2 id="何时写-adr" tabindex="-1">何时写 ADR <a class="header-anchor" href="#何时写-adr" aria-label="Permalink to &quot;何时写 ADR&quot;">​</a></h2><p>满足任一条件时写：</p><ol><li>决策影响多个模块或长期方向（如记忆架构、插件系统）</li><li>引入/拒绝一个重要外部依赖</li><li>在多个可行方案中做了取舍，且理由不显然</li></ol><p>小的实现选择（函数拆分、命名等）不需要 ADR。</p><h2 id="格式" tabindex="-1">格式 <a class="header-anchor" href="#格式" aria-label="Permalink to &quot;格式&quot;">​</a></h2><p>每条 ADR 一个文件，命名 <code>NNNN-短横线标题.md</code>，包含：</p><ul><li><strong>状态</strong>：Proposed（待评审）/ Accepted（已采纳）/ Superseded by NNNN（被取代）</li><li><strong>背景</strong>：问题与约束</li><li><strong>决策</strong>：做了什么决定</li><li><strong>理由</strong>：为什么，及放弃的备选方案</li><li><strong>后果</strong>：正面/负面影响、迁移与复审条件</li></ul><h2 id="索引" tabindex="-1">索引 <a class="header-anchor" href="#索引" aria-label="Permalink to &quot;索引&quot;">​</a></h2><table tabindex="0"><thead><tr><th>编号</th><th>标题</th><th>状态</th><th>日期</th></tr></thead><tbody><tr><td><a href="./0001-llm-mode-memory.html">0001</a></td><td>LLM Mode 记忆系统 — categories + wiki-links 取代 Neo4j 语义节点</td><td>Accepted</td><td>2026-07-08（修订 2026-07-10）</td></tr><tr><td><a href="./0002-memu-design-not-dependency.html">0002</a></td><td>memU — 借鉴设计而非引入依赖</td><td>Accepted</td><td>2026-07-08（修订 2026-07-10）</td></tr></tbody></table>',13)])])}const m=e(o,[["render",i]]);export{p as __pageData,m as default};
